insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LOG-301', 'Knows the Roads, Cannot Read the Route Economics', 'Founder Psychology', 'internal', 'The founder knows every lane, every driver and every checkpoint. What one trip actually leaves after fuel, the empty return leg, detention and the driver''s time has never been worked out, so busy months lose money.', 5, 9, '["Deep operational knowledge, weak numbers", "Empty return legs not costed", "Detention time absorbed silently", "Cannot say which lane earns"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["logistics"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-301-1', (select problem_id from problems where problem_code = 'LOG-301'), 'Trip Costing Never Learned', 'Knowledge', 'Nobody taught the founder to cost a trip including the empty leg, waiting time and driver hours.', 0.77, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-301-2', (select problem_id from problems where problem_code = 'LOG-301'), 'Operations Is the Comfortable Work', 'Psychological', 'Solving today''s routing feels like real work; the arithmetic feels like paperwork.', 0.72, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-301-3', (select problem_id from problems where problem_code = 'LOG-301'), 'Busy Mistaken for Profitable', 'Behavioural', 'A full fleet is treated as a good month, so thin trips are never identified.', 0.68, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-301-1', (select problem_id from problems where problem_code = 'LOG-301'), '["RC-LOG-301-1", "RC-LOG-301-2", "RC-LOG-301-3"]'::jsonb, 'Founder Leverage', 'Logistics & Supply Chain — Founder Skill Fit', '[]'::jsonb, '["Take your last twenty trips and cost each one properly, including the empty return.", "Sort them by what was actually left.", "Stop quoting the bottom five lanes at that price."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["A truck that is always moving is not the same as a truck that is earning.", "Twenty trips costed properly beats a fleet costed by feel."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-301-2', (select problem_id from problems where problem_code = 'LOG-301'), '["RC-LOG-301-1", "RC-LOG-301-2", "RC-LOG-301-3"]'::jsonb, 'Founder Leverage', 'Logistics & Supply Chain — Founder Skill Fit', '[]'::jsonb, '["Write the two things this business needs that you have never done.", "Take the bigger one to someone who has run fleet finance.", "Do it yourself for a quarter before handing it over."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["Name the gap before trying to close it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into questions (question_code, category, question_text, problem_id, root_cause_id, question_type, difficulty_level, priority, is_distress_tagged, red_flag_pattern, green_flag_pattern, primary_stage_group, industry_relevance) values ('S0-LOG-301-1', 'Founder Psychology', 'Do you know what one trip leaves you after everything?', (select problem_id from problems where problem_code = 'LOG-301'), (select root_cause_id from root_causes where root_cause_code = 'RC-LOG-301-1'), 'open_text', 2, 'CORE', false, 'No', 'Yes, all costs added', 'Stage 0', '["logistics"]'::jsonb) on conflict (question_code) do nothing;
