insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LOG-302', 'The Phone Never Stops and the Founder Always Answers', 'Founder Psychology', 'internal', 'A driver is stuck, a customer wants an update, a vehicle broke down. The founder is dispatch, customer service and breakdown support all day, so the work that would make the next week calmer never begins.', 5, 9, '["Founder is dispatch and support", "Phone never stops", "No time for process or new lanes", "The same problems every week"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["logistics"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-302-1', (select problem_id from problems where problem_code = 'LOG-302'), 'Answering Instead of Fixing', 'Behavioural', 'Each call is handled personally and the reason the calls keep coming is never addressed.', 0.77, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-302-2', (select problem_id from problems where problem_code = 'LOG-302'), 'No Hours Reserved', 'Operational', 'No time is protected for process or planning, so only the ringing phone gets attention.', 0.72, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-302-3', (select problem_id from problems where problem_code = 'LOG-302'), 'Being Reachable Feels Like Service', 'Psychological', 'The founder believes customers stay because they can always reach them, so stepping back feels like losing them.', 0.67, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-302-1', (select problem_id from problems where problem_code = 'LOG-302'), '["RC-LOG-302-1", "RC-LOG-302-2", "RC-LOG-302-3"]'::jsonb, 'Founder Leverage', 'Logistics & Supply Chain — Founder Time Use', '[]'::jsonb, '["Write down every call for one week and what it was about.", "Group them and fix the cause of the biggest group -- a tracking link, a written update schedule, a second dispatcher.", "Count that group again next week."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["A call that repeats is a missing process, not a busy phone.", "Count before and after or you will not know it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-302-2', (select problem_id from problems where problem_code = 'LOG-302'), '["RC-LOG-302-1", "RC-LOG-302-2", "RC-LOG-302-3"]'::jsonb, 'Founder Leverage', 'Logistics & Supply Chain — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the ones only you could have done.", "Hand dispatch to one person with the rules written down."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["Dispatch is a rules job once the rules exist."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
