insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LOG-303', 'The Rates and the Relationships Are All in One Head', 'Founder Psychology', 'internal', 'What each customer pays, what each driver is owed, which transporter to call at midnight — none of it is written. So nothing moves without the founder and the business cannot be in two cities.', 5, 9, '["Rates not written down", "Driver and transporter relationships personal", "Nothing moves without the founder", "Cannot open a second branch"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["logistics"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-303-1', (select problem_id from problems where problem_code = 'LOG-303'), 'Rates and Terms Never Written', 'Knowledge', 'What each customer pays and each partner is owed lives in the founder''s memory, so nobody else can quote or settle.', 0.78, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-303-2', (select problem_id from problems where problem_code = 'LOG-303'), 'Relationships Not Transferred', 'Operational', 'Drivers and transporters deal with the founder personally and nobody else has the standing.', 0.73, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-303-3', (select problem_id from problems where problem_code = 'LOG-303'), 'Holding It Feels Like Control', 'Psychological', 'Keeping the rates in one head feels like protecting margin, so writing them down feels like giving it away.', 0.66, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-303-1', (select problem_id from problems where problem_code = 'LOG-303'), '["RC-LOG-303-1", "RC-LOG-303-2", "RC-LOG-303-3"]'::jsonb, 'Founder Leverage', 'Logistics & Supply Chain — Founder Dependency', '[]'::jsonb, '["Write the rate card: what each customer pays on each lane, and what you pay out.", "Put it where whoever quotes can read it.", "Let someone else quote the next three enquiries and check them afterwards."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["A rate only you know is a rate only you can quote.", "Check the quotes afterwards, not before."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-303-2', (select problem_id from problems where problem_code = 'LOG-303'), '["RC-LOG-303-1", "RC-LOG-303-2", "RC-LOG-303-3"]'::jsonb, 'Founder Leverage', 'Logistics & Supply Chain — Founder Dependency', '[]'::jsonb, '["List your drivers and transporters with terms and contacts.", "Introduce one other person to your three most important ones.", "Let them handle the next routine booking."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["A relationship only one person holds is a risk, not an asset."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
