insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LOG-304', 'Dispatch, Billing and Complaints Land on Whoever Is There', 'Team & Leadership', 'internal', 'Nobody owns dispatch, nobody owns invoicing, nobody owns a complaint. So a delayed shipment gets three people and an unpaid invoice gets none.', 5, 9, '["No owner for dispatch or billing", "Complaints handled by whoever answers", "Unpaid invoices unowned", "Nobody accountable for a delay"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["logistics"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-304-1', (select problem_id from problems where problem_code = 'LOG-304'), 'Roles Never Set', 'Behavioural', 'The team grew by adding hands to whatever was urgent rather than by defining jobs.', 0.76, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-304-2', (select problem_id from problems where problem_code = 'LOG-304'), 'Everyone Handles Everything', 'Psychological', 'A team where anyone picks up anything feels responsive, which hides that nothing is owned.', 0.70, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-304-3', (select problem_id from problems where problem_code = 'LOG-304'), 'Handovers Unwritten', 'Operational', 'What must be true before a trip moves from booking to dispatch to billing was never agreed.', 0.69, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-304-1', (select problem_id from problems where problem_code = 'LOG-304'), '["RC-LOG-304-1", "RC-LOG-304-2", "RC-LOG-304-3"]'::jsonb, 'Team Effectiveness', 'Logistics & Supply Chain — Role Clarity', '[]'::jsonb, '["List the stages: booking, dispatch, delivery proof, invoice, collection.", "Put one name against each.", "Write what must be complete before each handover."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["One owner per stage, even if one person owns two.", "Invoices go missing at the handover, not inside the stage."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-304-2', (select problem_id from problems where problem_code = 'LOG-304'), '["RC-LOG-304-1", "RC-LOG-304-2", "RC-LOG-304-3"]'::jsonb, 'Team Effectiveness', 'Logistics & Supply Chain — Role Clarity', '[]'::jsonb, '["Pick the stage that failed most last month.", "Give it one owner and tell everyone.", "Review that stage alone next month."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["One owner properly assigned beats a new structure."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
