insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LOG-305', 'Nobody Can Quote, Discount or Accept a Claim', 'Team & Leadership', 'internal', 'A dispatcher cannot quote a lane, cannot agree a small discount, and cannot settle a damage claim. Customers wait, and in a trade where the load goes to whoever answers first, waiting loses the load.', 5, 9, '["Dispatchers cannot quote", "No discount authority", "Damage claims all escalate", "Loads lost while waiting"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["logistics"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-305-1', (select problem_id from problems where problem_code = 'LOG-305'), 'Limits Never Written', 'Operational', 'No rate floor or claim limit has been written down, so every decision needs the only person who knows the rule.', 0.78, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-305-2', (select problem_id from problems where problem_code = 'LOG-305'), 'Each Quote Feels Unique', 'Knowledge', 'Because past quotes were never turned into a rule, each is reasoned from scratch.', 0.72, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-305-3', (select problem_id from problems where problem_code = 'LOG-305'), 'Margin Feels Too Thin to Delegate', 'Psychological', 'The founder believes any concession could wipe out the margin, so nobody else is allowed to make one.', 0.67, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-305-1', (select problem_id from problems where problem_code = 'LOG-305'), '["RC-LOG-305-1", "RC-LOG-305-2", "RC-LOG-305-3"]'::jsonb, 'Team Effectiveness', 'Logistics & Supply Chain — Decision Rights', '[]'::jsonb, '["Write the rate floor per lane: below this, we do not take the load.", "Write the claim rule: what may be settled, up to what value, by whom.", "Let the team work inside both for a month and review the totals."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["A written floor quotes faster than you can answer the phone.", "Review what the rules produced, not each quote."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
