insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LOG-307', 'Wants Contract Business, Runs on Spot Loads', 'Strategy & Planning', 'internal', 'The founder talks about long-term contracts and dedicated fleets, and takes every spot load that comes because it pays this week. Nothing about how the business runs would satisfy a contract customer.', 5, 9, '["Wants contracts, runs on spot", "No records a contract buyer would want", "No consistency to sell", "Contract business out of reach"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["logistics"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-307-1', (select problem_id from problems where problem_code = 'LOG-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'Nobody holds the load mix against the stated ambition, so the gap grows quietly.', 0.78, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-307-2', (select problem_id from problems where problem_code = 'LOG-307'), 'Spot Loads Pay This Week', 'Behavioural', 'A spot load brings money now, so it always wins against building what a contract needs.', 0.73, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-307-3', (select problem_id from problems where problem_code = 'LOG-307'), 'Goal Never Described as Requirements', 'Knowledge', 'A contract business was never written down as what a contract customer actually requires.', 0.67, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-307-1', (select problem_id from problems where problem_code = 'LOG-307'), '["RC-LOG-307-1", "RC-LOG-307-2", "RC-LOG-307-3"]'::jsonb, 'Strategic Focus', 'Logistics & Supply Chain — Plan and Vision', '[]'::jsonb, '["Write what a contract customer needs before they sign: records, reliability figures, capacity, insurance.", "Mark which you have.", "Build the missing one that takes longest, starting now."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["A contract is a list of requirements, not a bigger relationship.", "Start with the slowest missing piece."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LOG-307-2', (select problem_id from problems where problem_code = 'LOG-307'), '["RC-LOG-307-1", "RC-LOG-307-2", "RC-LOG-307-3"]'::jsonb, 'Strategic Focus', 'Logistics & Supply Chain — Plan and Vision', '[]'::jsonb, '["List last quarter''s loads and mark each spot or repeat.", "Work out the share that was spot.", "Decide the share you want and quote accordingly."]'::jsonb, '[3, 4, 5]'::jsonb, '["logistics"]'::jsonb, '["Decide the mix on purpose rather than discovering it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
