insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LOG-308', 'New Vehicles, a New City and a Tracking System, Together', 'Strategy & Planning', 'internal', 'A fleet purchase, a branch in a second city and a tracking rollout are all live while collections are behind. The collection is what decides whether the other three are affordable.', 5, 9, '["Fleet purchase and expansion together", "Tracking rollout in parallel", "Collections behind", "Cash problem not prioritised"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["logistics"]'::jsonb) on conflict (problem_code) do nothing;
