insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LOG-309', 'Which Customer Pays Late and Which Route Floods Is Not Written', 'Strategy & Planning', 'internal', 'Which customer disputes every invoice, which route is impassable in the rains, which transporter lost a consignment — all in memory. So the same customer gets credit and the same route gets booked.', 5, 9, '["Customer payment history not recorded", "Route problems relearned each year", "Transporter failures not tracked", "Knowledge leaves with people"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["logistics"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-309-1', (select problem_id from problems where problem_code = 'LOG-309'), 'Nothing Written Down', 'Operational', 'Customer payment behaviour, route conditions and partner performance were never recorded.', 0.79, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-309-2', (select problem_id from problems where problem_code = 'LOG-309'), 'Memory Held by People', 'Knowledge', 'What the business knows about customers and routes lives in a few heads.', 0.73, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LOG-309-3', (select problem_id from problems where problem_code = 'LOG-309'), 'Recording a Dispute Feels Like Blame', 'Psychological', 'Writing up a customer''s bad behaviour feels like damaging the relationship, so it is not written.', 0.66, 'internal', 'Stage 0→1', '["logistics"]'::jsonb) on conflict (root_cause_code) do nothing;
