insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MKT-301', 'Brilliant at the Work, Has Never Run an Agency', 'Founder Psychology', 'internal', 'The founder does excellent creative work and clients love it. Pricing a retainer, costing a team''s time against it, and saying what is out of scope are things they have never learned, so good work is done at a loss.', 5, 9, '["Strong craft, weak commercials", "Retainers priced by feel", "Team time not costed against fees", "Cannot say which client is profitable"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["adtech_marketing"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-301-1', (select problem_id from problems where problem_code = 'MKT-301'), 'Agency Economics Never Learned', 'Knowledge', 'Nobody taught the founder to cost a retainer against the hours it actually consumes.', 0.77, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-301-2', (select problem_id from problems where problem_code = 'MKT-301'), 'The Craft Is the Comfortable Work', 'Psychological', 'Making the work feels like the real job, so the commercial side keeps waiting for a quieter week.', 0.72, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-301-3', (select problem_id from problems where problem_code = 'MKT-301'), 'Scope Creep Treated as Service', 'Behavioural', 'Extra requests are absorbed to keep the client happy, and the cost is never counted.', 0.68, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MKT-301-1', (select problem_id from problems where problem_code = 'MKT-301'), '["RC-MKT-301-1", "RC-MKT-301-2", "RC-MKT-301-3"]'::jsonb, 'Founder Leverage', 'Marketing, Advertising & AdTech — Founder Skill Fit', '[]'::jsonb, '["Take your three biggest clients and count the hours each actually consumed last month.", "Compare that to what they paid.", "Raise or re-scope the worst one before taking on anyone new."]'::jsonb, '[3, 4, 5]'::jsonb, '["adtech_marketing"]'::jsonb, '["A client who loves you and loses you money is still a problem.", "Count the hours before renegotiating, not after."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MKT-301-2', (select problem_id from problems where problem_code = 'MKT-301'), '["RC-MKT-301-1", "RC-MKT-301-2", "RC-MKT-301-3"]'::jsonb, 'Founder Leverage', 'Marketing, Advertising & AdTech — Founder Skill Fit', '[]'::jsonb, '["Write what is in scope and what is not, for your standard retainer.", "Send it to your next new client before you start.", "Use it the next time someone asks for something extra."]'::jsonb, '[3, 4, 5]'::jsonb, '["adtech_marketing"]'::jsonb, '["Scope you never wrote down cannot be exceeded, only absorbed."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
