insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MKT-302', 'The Founder Is Still on Every Client Account', 'Founder Psychology', 'internal', 'Every review, every difficult call, every pitch has the founder in it. New business and building the agency get whatever is left, which is evenings.', 5, 9, '["Founder on every account", "Every pitch needs the founder", "New business gets leftover hours", "No time to build the agency"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["adtech_marketing"]'::jsonb) on conflict (problem_code) do nothing;
