insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-302-2', (select problem_id from problems where problem_code = 'MKT-302'), 'No Hours Reserved', 'Operational', 'No time is protected for new business or process, so it happens only when no client is asking.', 0.72, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
