insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-304-1', (select problem_id from problems where problem_code = 'MKT-304'), 'Roles Never Set', 'Behavioural', 'The team grew by everyone doing everything rather than by defining jobs.', 0.76, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
