insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MKT-305', 'Nobody Can Approve Work, Spend on Media or Agree a Discount', 'Team & Leadership', 'internal', 'Work waits for the founder''s approval, media spend waits for their sign-off, and nobody can agree a fee change. Campaigns miss their window while the approval sits in a queue.', 5, 9, '["All work waits for founder approval", "Media spend needs sign-off", "No fee authority", "Campaigns miss their window"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["adtech_marketing"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-305-1', (select problem_id from problems where problem_code = 'MKT-305'), 'Limits Never Written', 'Operational', 'No one wrote down what may be approved or spent, so the safe move is always to ask.', 0.78, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-305-2', (select problem_id from problems where problem_code = 'MKT-305'), 'Approval Feels Like Protection', 'Psychological', 'The founder believes their approval is what stops bad work going out, rather than the rules being written.', 0.72, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-305-3', (select problem_id from problems where problem_code = 'MKT-305'), 'Past Decisions Not Turned Into Rules', 'Knowledge', 'The same approvals have been given repeatedly and never written up, so each is reasoned again.', 0.67, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MKT-305-1', (select problem_id from problems where problem_code = 'MKT-305'), '["RC-MKT-305-1", "RC-MKT-305-2", "RC-MKT-305-3"]'::jsonb, 'Team Effectiveness', 'Marketing, Advertising & AdTech — Decision Rights', '[]'::jsonb, '["Write the approval rule: what may go out without you, for which clients.", "Write the media spend limit per person.", "Let the team work inside both for a month and review the results, not each item."]'::jsonb, '[3, 4, 5]'::jsonb, '["adtech_marketing"]'::jsonb, '["A written rule ships work faster than a fast approver.", "Review what the rules produced, not each use of them."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
