insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-309-1', (select problem_id from problems where problem_code = 'MKT-309'), 'Nothing Written Down', 'Operational', 'Why pitches were won or lost and what campaigns actually did were never recorded in one place.', 0.79, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-309-2', (select problem_id from problems where problem_code = 'MKT-309'), 'Memory Held by People', 'Knowledge', 'What the agency knows lives in individual inboxes and in a few heads.', 0.73, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MKT-309-3', (select problem_id from problems where problem_code = 'MKT-309'), 'Writing Up a Loss Feels Bad', 'Psychological', 'Recording a lost pitch or a weak campaign feels like documenting failure, so it is skipped.', 0.67, 'internal', 'Stage 0→1', '["adtech_marketing"]'::jsonb) on conflict (root_cause_code) do nothing;
