insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('NGO-301', 'Committed to the Cause, Has Never Raised Money Properly', 'Founder Psychology', 'internal', 'The founder understands the problem and the community better than any funder does. Writing a proposal a funder can say yes to, reporting against a grant, and building a donor pipeline are skills they have never had, so funding arrives by luck.', 5, 9, '["Deep cause knowledge, weak fundraising", "Proposals written in a rush", "No donor pipeline", "Funding arrives unpredictably"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["ngo"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-301-1', (select problem_id from problems where problem_code = 'NGO-301'), 'Fundraising Never Learned', 'Knowledge', 'Nobody taught the founder how funders decide, so proposals describe the need rather than the plan.', 0.77, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-301-2', (select problem_id from problems where problem_code = 'NGO-301'), 'Programme Work Is the Comfortable Ground', 'Psychological', 'Being with the community feels like the real work; asking for money feels like a distraction from it.', 0.72, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-301-3', (select problem_id from problems where problem_code = 'NGO-301'), 'Asking Feels Like Begging', 'Behavioural', 'The founder delays the ask because it feels undignified, so it happens only when money runs low.', 0.68, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-NGO-301-1', (select problem_id from problems where problem_code = 'NGO-301'), '["RC-NGO-301-1", "RC-NGO-301-2", "RC-NGO-301-3"]'::jsonb, 'Founder Leverage', 'Non-Profit, Social Impact & NGO — Founder Skill Fit', '[]'::jsonb, '["Take your last rejected proposal and ask the funder what was missing.", "Write down exactly what they said.", "Fix that one thing in the next proposal before writing anything new."]'::jsonb, '[3, 4, 5]'::jsonb, '["ngo"]'::jsonb, '["A funder will usually tell you why, if you ask after the decision.", "Fix one named weakness rather than rewriting everything."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
