insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('NGO-303', 'The Funders and the Community Both Trust One Person', 'Founder Psychology', 'internal', 'Funders give because of the founder and the community trusts because of the founder. Neither relationship is written down or shared, so the organisation is one person and would not survive their absence.', 5, 9, '["Funders relate only to the founder", "Community trust is personal", "Nothing written about either", "Organisation would not survive an absence"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["ngo"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-303-1', (select problem_id from problems where problem_code = 'NGO-303'), 'Relationships Not Transferred', 'Operational', 'Both funders and community deal with the founder personally and nobody else has the standing.', 0.78, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-303-2', (select problem_id from problems where problem_code = 'NGO-303'), 'Trust Feels Untransferable', 'Psychological', 'The founder believes the trust is between people and cannot be handed on, so it is never tested.', 0.73, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-303-3', (select problem_id from problems where problem_code = 'NGO-303'), 'No Handover Material', 'Knowledge', 'There is nothing a successor could learn either relationship from, so the dependency has no exit.', 0.67, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
