insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-304-3', (select problem_id from problems where problem_code = 'NGO-304'), 'Handovers Unwritten', 'Operational', 'What must be collected during a programme for the report to be written was never agreed, so data is gathered late.', 0.69, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
