insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('NGO-305', 'Nobody Can Spend, Commit or Turn Down a Grant', 'Team & Leadership', 'internal', 'A field coordinator cannot spend on an emergency, nobody can commit to a partner, and nobody but the founder can say a grant is not worth the conditions. So the field waits and unsuitable grants get accepted.', 5, 9, '["Field cannot spend in an emergency", "No one can commit to a partner", "Unsuitable grants accepted", "Decisions wait on the founder"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["ngo"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-305-1', (select problem_id from problems where problem_code = 'NGO-305'), 'Limits Never Written', 'Operational', 'No spending limit has been written down for anyone, so the field waits for permission it cannot get quickly.', 0.78, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-305-2', (select problem_id from problems where problem_code = 'NGO-305'), 'Accepting Every Grant Feels Obligatory', 'Psychological', 'Turning down funding feels irresponsible in a resource-scarce organisation, so conditions are never refused.', 0.73, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-305-3', (select problem_id from problems where problem_code = 'NGO-305'), 'No Criteria for a Good Grant', 'Knowledge', 'Nobody wrote down what makes a grant worth its reporting burden, so each is judged by whoever reads it.', 0.67, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
