insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('NGO-306', 'Hiring People Who Believe, Without Checking They Can Do It', 'Team & Leadership', 'internal', 'Commitment to the cause is the main test and it is a real one. Whether the person can actually run a programme or write a report is never checked, so good people are placed in jobs they cannot do.', 5, 9, '["Hired on commitment alone", "Capability not tested", "Good people in wrong roles", "No written job description"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["ngo"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-306-1', (select problem_id from problems where problem_code = 'NGO-306'), 'No Written Role or Test', 'Operational', 'Hiring starts from someone believing in the cause rather than from a written job with a way to test it.', 0.77, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-306-2', (select problem_id from problems where problem_code = 'NGO-306'), 'Commitment Read as Capability', 'Behavioural', 'Because candidates care deeply, their ability to do the specific job is assumed rather than checked.', 0.73, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-306-3', (select problem_id from problems where problem_code = 'NGO-306'), 'Nothing Learned Between Hires', 'Knowledge', 'Who turned out able and why is never written down, so the pattern is never seen.', 0.67, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-NGO-306-1', (select problem_id from problems where problem_code = 'NGO-306'), '["RC-NGO-306-1", "RC-NGO-306-2", "RC-NGO-306-3"]'::jsonb, 'Team Effectiveness', 'Non-Profit, Social Impact & NGO — Hiring Repeatability', '[]'::jsonb, '["Write the job before you look: the five things this person must do in month one.", "Write how you will test each one -- a real report, a real session plan.", "Give every candidate the same test and write down what you saw."]'::jsonb, '[3, 4, 5]'::jsonb, '["ngo"]'::jsonb, '["Commitment is the entry requirement, not the assessment.", "Test the work; it is kinder than placing someone where they will fail."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-NGO-306-2', (select problem_id from problems where problem_code = 'NGO-306'), '["RC-NGO-306-1", "RC-NGO-306-2", "RC-NGO-306-3"]'::jsonb, 'Team Effectiveness', 'Non-Profit, Social Impact & NGO — Hiring Repeatability', '[]'::jsonb, '["Look at anyone struggling in their role right now.", "Ask whether the job was ever written down.", "Write it, and agree with them what support gets them there."]'::jsonb, '[3, 4, 5]'::jsonb, '["ngo"]'::jsonb, '["Someone failing an unwritten job was set up to fail."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
