insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('NGO-307', 'Says Systems Change, Delivers Direct Service', 'Strategy & Planning', 'internal', 'The founder describes changing how a system works, and everything the organisation does is direct service to individuals. Each service was a real person in front of them, and together they are a delivery organisation.', 5, 9, '["Says systems change, delivers direct service", "No systemic work in the plan", "Cannot say what would change the system", "Funders hear one thing and fund another"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["ngo"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-307-1', (select problem_id from problems where problem_code = 'NGO-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'Nobody holds the programme against the stated theory of change, so the drift is never seen.', 0.78, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
