insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('NGO-308', 'Three Programmes, Two Grant Applications and an Audit', 'Strategy & Planning', 'internal', 'Everything is running at once on a team that cannot cover it, and the grant applications are the ones with someone else''s deadline. Staff are stretched across all of it and none of it is done well.', 5, 9, '["Too many programmes for the team", "Grant deadlines competing with delivery", "Audit running alongside", "Staff stretched across everything"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["ngo"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-308-1', (select problem_id from problems where problem_code = 'NGO-308'), 'Nothing Ranked', 'Strategic', 'Work is listed rather than ordered, so a funding deadline competes with three programmes on equal terms.', 0.78, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
