insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-308-3', (select problem_id from problems where problem_code = 'NGO-308'), 'Capacity Never Counted', 'Knowledge', 'Nobody has written down how many programmes the team can actually run well, so more keep being added.', 0.68, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
