insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('NGO-309', 'The Programme History Lives in Field Notebooks', 'Strategy & Planning', 'internal', 'What worked in which village, which partner failed to deliver, what last year''s numbers actually were — in notebooks, in phones, and in the heads of field staff who move on. So the next programme starts from nothing.', 5, 9, '["Programme learnings in notebooks", "Partner failures not recorded", "Last year''s numbers hard to find", "Knowledge leaves with field staff"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["ngo"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-309-1', (select problem_id from problems where problem_code = 'NGO-309'), 'Nothing Written Centrally', 'Operational', 'What each programme did and learned was never recorded in one place, so the organisation cannot learn from itself.', 0.79, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-309-2', (select problem_id from problems where problem_code = 'NGO-309'), 'Memory Held by People', 'Knowledge', 'What the organisation knows lives with field staff, and field staff turnover is high.', 0.73, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-NGO-309-3', (select problem_id from problems where problem_code = 'NGO-309'), 'Reviewing Feels Like Criticising the Team', 'Psychological', 'Honestly reviewing a programme that did not work feels like blaming committed people, so it is skipped.', 0.67, 'internal', 'Stage 0→1', '["ngo"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-NGO-309-1', (select problem_id from problems where problem_code = 'NGO-309'), '["RC-NGO-309-1", "RC-NGO-309-2", "RC-NGO-309-3"]'::jsonb, 'Strategic Focus', 'Non-Profit, Social Impact & NGO — What Gets Remembered', '[]'::jsonb, '["Start one page per programme site: what you did, what happened, what you would change.", "Fill it in monthly, in the field, not at year end.", "Read the pages before designing the next programme."]'::jsonb, '[3, 4, 5]'::jsonb, '["ngo"]'::jsonb, '["A programme you did not write down cannot teach the next one.", "Write it in the field or it will not be written."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-NGO-309-2', (select problem_id from problems where problem_code = 'NGO-309'), '["RC-NGO-309-1", "RC-NGO-309-2", "RC-NGO-309-3"]'::jsonb, 'Strategic Focus', 'Non-Profit, Social Impact & NGO — What Gets Remembered', '[]'::jsonb, '["Write one page per partner: what they committed and what they delivered.", "Read it before the next partnership.", "Turn the worst pattern into a partnership rule."]'::jsonb, '[3, 4, 5]'::jsonb, '["ngo"]'::jsonb, '["A lesson with no rule attached is a story."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
