insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PHM-301', 'A Real Scientist Who Has Never Costed a Programme', 'Founder Psychology', 'internal', 'The founder knows the science and the data is genuinely promising. What the next phase costs, how long regulatory review takes, and how much money is needed before any revenue exists have never been worked out, so the runway assumption is optimistic by years.', 5, 9, '["Strong science, weak programme planning", "Phase costs not worked out", "Regulatory timelines underestimated", "Funding need badly understated"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["pharma_biotech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-301-1', (select problem_id from problems where problem_code = 'PHM-301'), 'Programme Economics Never Learned', 'Knowledge', 'Nobody taught the founder to build a cost and time plan for a development programme.', 0.77, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-301-2', (select problem_id from problems where problem_code = 'PHM-301'), 'The Science Is the Comfortable Ground', 'Psychological', 'Working on the data feels like progress; the programme plan feels like administration.', 0.72, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-301-3', (select problem_id from problems where problem_code = 'PHM-301'), 'Optimism Treated as Planning', 'Behavioural', 'Best-case timelines are used as the plan, so every slip is a surprise rather than a scenario.', 0.68, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PHM-301-1', (select problem_id from problems where problem_code = 'PHM-301'), '["RC-PHM-301-1", "RC-PHM-301-2", "RC-PHM-301-3"]'::jsonb, 'Founder Leverage', 'Pharmaceuticals & Biotech — Founder Skill Fit', '[]'::jsonb, '["Write the next phase as a plan: every activity, its cost, its duration, who does it.", "Add the regulatory review time as its own line, from published timelines not hope.", "Compare the total to the money you have."]'::jsonb, '[3, 4, 5]'::jsonb, '["pharma_biotech"]'::jsonb, '["A programme plan with no regulatory waiting time in it is not a plan.", "Use published timelines, not the best case you have heard of."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PHM-301-2', (select problem_id from problems where problem_code = 'PHM-301'), '["RC-PHM-301-1", "RC-PHM-301-2", "RC-PHM-301-3"]'::jsonb, 'Founder Leverage', 'Pharmaceuticals & Biotech — Founder Skill Fit', '[]'::jsonb, '["Write the two things this business needs that you have never done.", "Take the bigger one to someone who has run a development programme.", "Have them review your plan before you take it to an investor."]'::jsonb, '[3, 4, 5]'::jsonb, '["pharma_biotech"]'::jsonb, '["Name the gap before trying to close it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
