insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PHM-302', 'The Founder Is Still at the Bench', 'Founder Psychology', 'internal', 'The founder runs experiments themselves because they are the best scientist in the building. Investor conversations, regulatory preparation and hiring get the hours left over, which in a funding-dependent business is the wrong way round.', 5, 9, '["Founder still runs experiments", "Investor work gets leftover hours", "Regulatory preparation slipping", "Hiring delayed"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["pharma_biotech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-302-1', (select problem_id from problems where problem_code = 'PHM-302'), 'Best Scientist Does the Science', 'Behavioural', 'The founder is genuinely the strongest scientist, so the work keeps landing on them and never transfers.', 0.76, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
