insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PHM-303', 'Only the Founder Can Explain the Science', 'Founder Psychology', 'internal', 'Every investor meeting, every partner conversation and every regulatory discussion needs the founder, because the scientific argument was never written down in a form anyone else could carry.', 5, 9, '["Founder in every external conversation", "Scientific argument unwritten", "Partnering cannot run without the founder", "Growth limited by one diary"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["pharma_biotech"]'::jsonb) on conflict (problem_code) do nothing;
