insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-303-3', (select problem_id from problems where problem_code = 'PHM-303'), 'No Handover Material Exists', 'Operational', 'There is nothing a business development hire could learn the science from, so the dependency has no exit.', 0.67, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PHM-303-1', (select problem_id from problems where problem_code = 'PHM-303'), '["RC-PHM-303-1", "RC-PHM-303-2", "RC-PHM-303-3"]'::jsonb, 'Founder Leverage', 'Pharmaceuticals & Biotech — Founder Dependency', '[]'::jsonb, '["Write the scientific case as you actually make it, with the three questions you always get.", "Have a non-scientist deliver it to a friendly contact while you listen silently.", "Fix what the material got wrong, not what the person got wrong."]'::jsonb, '[3, 4, 5]'::jsonb, '["pharma_biotech"]'::jsonb, '["If they cannot deliver it from the page, the page is wrong.", "Listening without interrupting is the only honest test."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
