insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PHM-304', 'Science, Quality and Regulatory Are the Same People', 'Team & Leadership', 'internal', 'The scientist who generates the data also reviews it and also assembles the regulatory file. Nobody checks anyone else''s work independently, which in a regulated business is the finding waiting to happen.', 5, 9, '["Data generated and reviewed by the same person", "No independent quality function", "Regulatory file assembled by the scientists", "No separation of duties"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["pharma_biotech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-304-1', (select problem_id from problems where problem_code = 'PHM-304'), 'Roles Never Set', 'Behavioural', 'The team formed around available scientists rather than around the separated roles a regulated programme needs.', 0.77, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-304-2', (select problem_id from problems where problem_code = 'PHM-304'), 'Small Team Used as the Reason', 'Psychological', 'Being small is treated as a reason separation is impossible, rather than a reason to define it early.', 0.71, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-304-3', (select problem_id from problems where problem_code = 'PHM-304'), 'Handovers Unwritten', 'Operational', 'What must be reviewed and by whom before data enters a submission was never agreed in writing.', 0.69, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
