insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PHM-305', 'Every Protocol Deviation Reaches the Founder', 'Team & Leadership', 'internal', 'Whether a deviation matters, whether a batch can be used, whether a result is reportable — all of it escalates, because none of it was written as criteria. Work stops while the founder is in a meeting.', 5, 9, '["All deviations escalate", "No written criteria for acceptability", "Work stops waiting", "Team stops deciding anything"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["pharma_biotech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-305-1', (select problem_id from problems where problem_code = 'PHM-305'), 'Rules Never Written', 'Operational', 'The founder''s scientific judgement was never turned into criteria, so every deviation needs them personally.', 0.78, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-305-2', (select problem_id from problems where problem_code = 'PHM-305'), 'Regulatory Risk Used to Justify the Bottleneck', 'Psychological', 'Because the stakes are regulatory, centralising every call feels responsible rather than slow.', 0.73, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-305-3', (select problem_id from problems where problem_code = 'PHM-305'), 'No Safe Line to Delegate Across', 'Knowledge', 'There is no written line between what may be decided and what must escalate, so everything escalates.', 0.67, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PHM-305-1', (select problem_id from problems where problem_code = 'PHM-305'), '["RC-PHM-305-1", "RC-PHM-305-2", "RC-PHM-305-3"]'::jsonb, 'Team Effectiveness', 'Pharmaceuticals & Biotech — Decision Rights', '[]'::jsonb, '["Write the criteria for what is clearly acceptable and what clearly is not.", "Write the short list of things that must always come to you.", "Let the team work the clear cases for a quarter and review the escalations, not every case."]'::jsonb, '[3, 4, 5]'::jsonb, '["pharma_biotech"]'::jsonb, '["Write the escalation line so the team knows both sides of it.", "In a regulated business the written rule is the safeguard, not the approval."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PHM-305-2', (select problem_id from problems where problem_code = 'PHM-305'), '["RC-PHM-305-1", "RC-PHM-305-2", "RC-PHM-305-3"]'::jsonb, 'Team Effectiveness', 'Pharmaceuticals & Biotech — Decision Rights', '[]'::jsonb, '["List the ten deviations you were asked about last month.", "Mark which were genuinely borderline.", "Turn the clear ones into written criteria this week."]'::jsonb, '[3, 4, 5]'::jsonb, '["pharma_biotech"]'::jsonb, '["If most escalations were not borderline, the rule was missing."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
