insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-306-3', (select problem_id from problems where problem_code = 'PHM-306'), 'Same Network, Same Blind Spots', 'Strategic', 'Hiring from one lab reproduces its gaps, so the regulatory and commercial skills stay missing.', 0.69, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
