insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PHM-308', 'Three Programmes on One Team''s Capacity', 'Strategy & Planning', 'internal', 'Three candidate molecules are being advanced together on a team and a budget that can carry one properly. All three move slowly, none reaches a decision point, and the money runs out with three half-answers.', 5, 9, '["Three programmes on one team''s capacity", "All moving slowly", "No programme reaching a decision point", "Money spread too thin"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["pharma_biotech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-308-1', (select problem_id from problems where problem_code = 'PHM-308'), 'Nothing Ranked', 'Strategic', 'Programmes are run in parallel rather than ordered, so none reaches the data that would justify the next raise.', 0.79, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-308-2', (select problem_id from problems where problem_code = 'PHM-308'), 'Killing a Programme Feels Like Failure', 'Psychological', 'Stopping a molecule feels like admitting the science was wrong, so nothing is stopped.', 0.74, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-308-3', (select problem_id from problems where problem_code = 'PHM-308'), 'Decision Points Never Defined', 'Knowledge', 'Nobody wrote down what result would justify continuing or stopping each programme.', 0.68, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PHM-308-1', (select problem_id from problems where problem_code = 'PHM-308'), '["RC-PHM-308-1", "RC-PHM-308-2", "RC-PHM-308-3"]'::jsonb, 'Strategic Focus', 'Pharmaceuticals & Biotech — Prioritisation', '[]'::jsonb, '["Write the decision point for each programme: what result continues it, what result stops it.", "Fund the one nearest its decision point properly.", "Pause the others and say so, rather than starving all three."]'::jsonb, '[3, 4, 5]'::jsonb, '["pharma_biotech"]'::jsonb, '["Three half-answers raise nothing; one clear answer raises a round.", "A written stop criterion makes stopping a decision, not a failure."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PHM-308-2', (select problem_id from problems where problem_code = 'PHM-308'), '["RC-PHM-308-1", "RC-PHM-308-2", "RC-PHM-308-3"]'::jsonb, 'Strategic Focus', 'Pharmaceuticals & Biotech — Prioritisation', '[]'::jsonb, '["List each programme and what it needs to reach a decision.", "Rank by which is cheapest to answer.", "Pause the bottom two this month."]'::jsonb, '[3, 4, 5]'::jsonb, '["pharma_biotech"]'::jsonb, '["Answer the cheapest question first."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
