insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PHM-309', 'The Experimental History Lives in Notebooks and Heads', 'Strategy & Planning', 'internal', 'Which batch behaved oddly, why an assay was changed, what the failed experiment two years ago actually showed — in notebooks and in the memory of people who may leave. In a regulated business that is both a slowdown and a risk.', 5, 9, '["Experimental history in notebooks only", "Assay changes not explained", "Failed experiments not written up", "Regulatory history depends on memory"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["pharma_biotech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-309-1', (select problem_id from problems where problem_code = 'PHM-309'), 'Nothing Written Centrally', 'Operational', 'Results, changes and their reasons were never recorded in one searchable place, so work is repeated and cannot be evidenced.', 0.79, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-309-2', (select problem_id from problems where problem_code = 'PHM-309'), 'Memory Held by People', 'Knowledge', 'What the company knows lives with individual scientists and leaves when they do.', 0.74, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PHM-309-3', (select problem_id from problems where problem_code = 'PHM-309'), 'Writing Up a Failure Feels Bad', 'Psychological', 'Documenting a failed experiment feels like recording a waste of money, so it is skipped.', 0.67, 'internal', 'Stage 0→1', '["pharma_biotech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PHM-309-1', (select problem_id from problems where problem_code = 'PHM-309'), '["RC-PHM-309-1", "RC-PHM-309-2", "RC-PHM-309-3"]'::jsonb, 'Strategic Focus', 'Pharmaceuticals & Biotech — What Gets Remembered', '[]'::jsonb, '["Start one page per experiment that failed: what you expected, what happened, what you concluded.", "Fill it in the week the result comes back.", "Read the pages before designing anything similar."]'::jsonb, '[3, 4, 5]'::jsonb, '["pharma_biotech"]'::jsonb, '["A failed experiment you wrote up is data; one you did not is a repeat.", "Write the expectation first or the result means nothing."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PHM-309-2', (select problem_id from problems where problem_code = 'PHM-309'), '["RC-PHM-309-1", "RC-PHM-309-2", "RC-PHM-309-3"]'::jsonb, 'Strategic Focus', 'Pharmaceuticals & Biotech — What Gets Remembered', '[]'::jsonb, '["Write down every assay or method change and why it was made.", "Keep it in one place with dates.", "Read it before any submission."]'::jsonb, '[3, 4, 5]'::jsonb, '["pharma_biotech"]'::jsonb, '["An unexplained method change is a question you will be asked later."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
