insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SVC-301', 'Excellent Consultant, Has Never Run a Firm', 'Founder Psychology', 'internal', 'Clients pay for the founder''s judgement and get real value. Pricing a piece of work rather than a day, costing a team against a fee, and knowing which engagement actually made money are things they have never learned.', 5, 9, '["Strong consulting, weak firm economics", "Prices by the day, not the work", "Team time not costed against fees", "Cannot say which engagement earned"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["services"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SVC-301-1', (select problem_id from problems where problem_code = 'SVC-301'), 'Firm Economics Never Learned', 'Knowledge', 'Nobody taught the founder to cost an engagement against the hours it consumes across the team.', 0.77, 'internal', 'Stage 0→1', '["services"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SVC-301-2', (select problem_id from problems where problem_code = 'SVC-301'), 'The Client Work Is the Comfortable Ground', 'Psychological', 'Doing the consulting feels like the real job, so the firm''s own numbers keep waiting.', 0.72, 'internal', 'Stage 0→1', '["services"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SVC-301-3', (select problem_id from problems where problem_code = 'SVC-301'), 'Day Rates Cap the Business', 'Behavioural', 'Selling days rather than outcomes ties revenue to hours and nobody has questioned it.', 0.68, 'internal', 'Stage 0→1', '["services"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SVC-301-1', (select problem_id from problems where problem_code = 'SVC-301'), '["RC-SVC-301-1", "RC-SVC-301-2", "RC-SVC-301-3"]'::jsonb, 'Founder Leverage', 'Professional Services & Consulting — Founder Skill Fit', '[]'::jsonb, '["Take your three most recent engagements and count every hour anyone spent.", "Compare that to the fee.", "Reprice or re-scope the worst one before selling the next."]'::jsonb, '[3, 4, 5]'::jsonb, '["services"]'::jsonb, '["An engagement that felt successful and lost money is still a loss.", "Count all the hours, including yours."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SVC-301-2', (select problem_id from problems where problem_code = 'SVC-301'), '["RC-SVC-301-1", "RC-SVC-301-2", "RC-SVC-301-3"]'::jsonb, 'Founder Leverage', 'Professional Services & Consulting — Founder Skill Fit', '[]'::jsonb, '["Take one recurring piece of work and price it as an outcome, not as days.", "Offer it that way to the next three prospects.", "Write down what each one said."]'::jsonb, '[3, 4, 5]'::jsonb, '["services"]'::jsonb, '["You cannot grow past your own hours while you sell hours."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
