insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SVC-302', 'The Founder Is Billable Five Days a Week', 'Founder Psychology', 'internal', 'Every day is on a client, because every billable day is revenue. Selling, recruiting and building anything that outlasts the founder happen in the evenings and mostly do not happen.', 5, 9, '["Founder billable every day", "Selling done in the evenings", "No time to build the firm", "Revenue stops when the founder stops"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["services"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SVC-302-1', (select problem_id from problems where problem_code = 'SVC-302'), 'Billable Work Pays Today', 'Behavioural', 'A billable day brings money this month, so it always wins against firm-building that pays later.', 0.77, 'internal', 'Stage 0→1', '["services"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SVC-302-2', (select problem_id from problems where problem_code = 'SVC-302'), 'No Hours Reserved', 'Operational', 'No time is protected for selling or building, so it happens only when no client is booked.', 0.72, 'internal', 'Stage 0→1', '["services"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SVC-302-3', (select problem_id from problems where problem_code = 'SVC-302'), 'Full Diary Feels Like Success', 'Psychological', 'A fully booked week feels like a healthy business, which hides that it cannot grow.', 0.68, 'internal', 'Stage 0→1', '["services"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SVC-302-1', (select problem_id from problems where problem_code = 'SVC-302'), '["RC-SVC-302-1", "RC-SVC-302-2", "RC-SVC-302-3"]'::jsonb, 'Founder Leverage', 'Professional Services & Consulting — Founder Time Use', '[]'::jsonb, '["Block one non-billable day a week and hold it for three months.", "Spend it only on selling and building.", "Compare your pipeline after three months to before."]'::jsonb, '[3, 4, 5]'::jsonb, '["services"]'::jsonb, '["A fully billable founder is a business with no future work.", "One day a week, held, beats a month of good intentions."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SVC-302-2', (select problem_id from problems where problem_code = 'SVC-302'), '["RC-SVC-302-1", "RC-SVC-302-2", "RC-SVC-302-3"]'::jsonb, 'Founder Leverage', 'Professional Services & Consulting — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week, split billable and firm.", "Decide the split you need and write it down.", "Tell your clients your availability before they book you."]'::jsonb, '[3, 4, 5]'::jsonb, '["services"]'::jsonb, '["Tell clients your availability rather than defending it afterwards."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
