insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SVC-303', 'Clients Bought the Founder''s Judgement', 'Founder Psychology', 'internal', 'Every client engaged because of the founder personally, and the way they think about a problem has never been written down. So the firm cannot deliver without them and cannot sell anything they are not delivering.', 5, 9, '["Clients bought the founder", "Method never written down", "Cannot sell work the founder will not deliver", "Growth limited by one diary"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["services"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SVC-303-1', (select problem_id from problems where problem_code = 'SVC-303'), 'Method Never Written', 'Knowledge', 'How the founder approaches a problem lives in their head and was never turned into a method anyone else could run.', 0.78, 'internal', 'Stage 0→1', '["services"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SVC-303-2', (select problem_id from problems where problem_code = 'SVC-303'), 'Nobody Else Trusted With a Client', 'Psychological', 'The founder fears a junior damaging a relationship, so nobody is given a client to lead.', 0.72, 'internal', 'Stage 0→1', '["services"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SVC-303-3', (select problem_id from problems where problem_code = 'SVC-303'), 'No Training Material', 'Operational', 'There is nothing a new consultant could learn the approach from, so the dependency has no exit.', 0.67, 'internal', 'Stage 0→1', '["services"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SVC-303-1', (select problem_id from problems where problem_code = 'SVC-303'), '["RC-SVC-303-1", "RC-SVC-303-2", "RC-SVC-303-3"]'::jsonb, 'Founder Leverage', 'Professional Services & Consulting — Founder Dependency', '[]'::jsonb, '["Write your approach as a method: the steps, the questions you always ask, what each step produces.", "Have someone else run step one with a real client while you observe.", "Fix what the method got wrong, not what the person got wrong."]'::jsonb, '[3, 4, 5]'::jsonb, '["services"]'::jsonb, '["A method on paper is the only thing you can sell without delivering it yourself.", "Observing without stepping in is the only honest test."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SVC-303-2', (select problem_id from problems where problem_code = 'SVC-303'), '["RC-SVC-303-1", "RC-SVC-303-2", "RC-SVC-303-3"]'::jsonb, 'Founder Leverage', 'Professional Services & Consulting — Founder Dependency', '[]'::jsonb, '["Pick your smallest client and hand it to someone else entirely.", "Stay out of it for one engagement.", "Ask the client at the end whether anything changed."]'::jsonb, '[3, 4, 5]'::jsonb, '["services"]'::jsonb, '["Ask the client, not yourself, whether your absence showed."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
