insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SVC-304-2', (select problem_id from problems where problem_code = 'SVC-304'), 'Selling Treated as Everyone''s Job', 'Psychological', 'Because everyone is told to sell, nobody is accountable when nobody does.', 0.71, 'internal', 'Stage 0→1', '["services"]'::jsonb) on conflict (root_cause_code) do nothing;
